package dev.gbppimentel.zzz;
import android.graphics.Bitmap;import com.googlecode.tesseract.android.TessBaseAPI;
final class OcrEngine {
 final TessBaseAPI api;
 OcrEngine(){api=new TessBaseAPI();if(!api.init(GameObserver.DIR.getPath(),"eng",TessBaseAPI.OEM_LSTM_ONLY))throw new IllegalStateException("OCR unavailable");api.setDebug(false);api.setVariable("user_defined_dpi","300");}
 String read(Bitmap source,int x,int y,int w,int h,boolean digits){return read(source,x,y,w,h,digits,digits?7:11);}
 String readLine(Bitmap source,int x,int y,int w,int h){return read(source,x,y,w,h,false,7);}
 private String read(Bitmap source,int x,int y,int w,int h,boolean digits,int mode){Bitmap crop=Bitmap.createBitmap(source,x,y,w,h);Bitmap scaled=Bitmap.createScaledBitmap(crop,w*(digits?3:2),h*(digits?3:2),true);if(digits){int[] pixels=new int[scaled.getWidth()*scaled.getHeight()];scaled.getPixels(pixels,0,scaled.getWidth(),0,0,scaled.getWidth(),scaled.getHeight());for(int i=0;i<pixels.length;i++){int p=pixels[i];int v=(((p>>16)&255)+((p>>8)&255)+(p&255))/3;pixels[i]=v>65?0xff000000:0xffffffff;}Bitmap binary=Bitmap.createBitmap(pixels,scaled.getWidth(),scaled.getHeight(),Bitmap.Config.ARGB_8888);scaled.recycle();scaled=binary;}try{api.setPageSegMode(mode);api.setVariable("tessedit_char_whitelist",digits?"0123456789UID: ":"");api.setImage(scaled);String text=api.getUTF8Text();return text==null?"":text.trim();}finally{api.clear();scaled.recycle();if(crop!=source)crop.recycle();}}

 /** Agree on a complete UID field; use numeral-only crops for bright backgrounds. */
 String uid(Bitmap source){String a=readLine(source,1650,1056,145,24),b=readLine(source,1675,1054,110,26);String x=ContextParser.uid(a),y=ContextParser.uid(b);if(!x.isEmpty()&&!y.isEmpty())return ContextParser.uidCrops(a,b,"","");return ContextParser.uidCrops(a,b,readLine(source,1694,1058,85,22),readLine(source,1692,1058,88,20));}

 String enemyName(Bitmap source,ContextParser parser){Bitmap crop=Bitmap.createBitmap(source,160,35,700,355);Bitmap scaled=Bitmap.createScaledBitmap(crop,1400,710,true);com.googlecode.tesseract.android.ResultIterator iterator=null;try{api.setPageSegMode(11);api.setVariable("tessedit_char_whitelist","");api.setImage(scaled);String full=api.getUTF8Text();org.json.JSONObject known=parser.enemy(full==null?"":full);if(known!=null)return known.optString("name");iterator=api.getResultIterator();if(iterator==null)return "";iterator.begin();String best="";double score=0;int[] pixels=new int[960*540];source.getPixels(pixels,0,960,0,0,960,540);do{String line=iterator.getUTF8Text(2);if(line==null)continue;line=line.trim();float confidence=iterator.confidence(2);if(confidence<78||!line.matches("[A-Za-z][A-Za-z0-9 '\u2019:\\-]{3,50}")||!parser.agent(line).isEmpty())continue;String lower=line.toLowerCase(java.util.Locale.ROOT);if(lower.matches(".*(challenge|damage|score|combo|trial|options|combat|restart|mission|remaining|objective|stage|hits taken|select|level|pause|maximum).*"))continue;int[] b=iterator.getBoundingBox(2);int x=160+b[0]/2,y=35+b[3]/2,width=(b[2]-b[0])/2;boolean bar=false;for(int yy=y;yy<Math.min(530,y+24)&&!bar;yy++){int run=0;for(int xx=Math.max(0,x-20);xx<Math.min(960,x+width+30);xx++){int color=pixels[yy*960+xx],r=(color>>16)&255,g=(color>>8)&255,blue=color&255;boolean strong=(r>150&&r>g*1.3&&r>blue*1.2)||EnemyBars.green(color);run=strong?run+1:0;if(run>=15){bar=true;break;}}}if(bar&&confidence>score){best=line;score=confidence;}}while(iterator.next(2));return best;
 }catch(Exception ignored){return "";}finally{if(iterator!=null)iterator.delete();api.clear();scaled.recycle();crop.recycle();}}
}
